const index = new Map(physConstants.map((k) => [k.id, k]));
function byId(id: string): PhysConstant {
  const k = index.get(id);
  if (!k) throw new Error('unknown constant: ' + id);
  return k;
}

/** Ходовые константы под короткими символами: PHYS.c.value, PHYS.h.value… */
export const PHYS = {
  c: byId('speed-of-light-in-vacuum'),
  h: byId('planck-constant'),
  hbar: byId('reduced-planck-constant'),
  e: byId('elementary-charge'),
  me: byId('electron-mass'),
  mp: byId('proton-mass'),
  mn: byId('neutron-mass'),
  NA: byId('avogadro-constant'),
  kB: byId('boltzmann-constant'),
  G: byId('newtonian-constant-of-gravitation'),
  alpha: byId('fine-structure-constant'),
  R: byId('molar-gas-constant'),
  u: byId('atomic-mass-constant'),
  eps0: byId('vacuum-electric-permittivity'),
  mu0: byId('vacuum-mag-permeability'),
  gn: byId('standard-acceleration-of-gravity'),
  sigma: byId('stefan-boltzmann-constant'),
  Ry: byId('rydberg-constant'),
  F: byId('faraday-constant'),
  muB: byId('bohr-magneton'),
  a0: byId('bohr-radius'),
  eV: byId('electron-volt'),
} as const;

export function constantById(id: string): PhysConstant | undefined {
  return index.get(id);
}
